impl Solution{pub fn solve(b:&mut Vec<Vec<char>>){if b.is_empty(){return}fn f(b:&mut Vec<Vec<char>>,i:i32,j:i32){if i<0||j<0||i>=b.len()as i32||j>=b[0].len()as i32||b[i as usize][j as usize]!='O'{return}b[i as usize][j as usize]='#';f(b,i+1,j);f(b,i-1,j);f(b,i,j+1);f(b,i,j-1);}let(m,n)=(b.len(),b[0].len());for i in 0..m{f(b,i as i32,0);f(b,i as i32,n as i32-1);}for j in 0..n{f(b,0,j as i32);f(b,m as i32-1,j as i32);}for r in b{for c in r{*c=if *c=='#'{'O'}else if *c=='O'{'X'}else{*c};}}}}
